attempts.query:
PREFIX energia: <https://w3id.org/rastro/energia#>
SELECT (COUNT(DISTINCT ?v) AS ?n) WHERE {
  ?v a energia:DetectedVenting ;
     energia:inConcession ?c ;
     energia:date ?d .
  FILTER(SUBSTR(STR(?d), 1, 10) >= "2024-01-01")
  ?s a energia:SurroundingsLink ;
     energia:aboutVenting ?v ;
     energia:protectedArea ?pa .
  FILTER(STRLEN(STR(?pa)) > 0)
}
